// Rust Axum API - Host-agnostisch und unsichtbare IP
// Cargo.toml dependencies:
// axum = "0.7"
// tokio = { version = "1.0", features = ["full"] }
// serde = { version = "1.0", features = ["derive"] }
// serde_json = "1.0"

use axum::{
    extract::{Host, Json},
    http::{HeaderMap, StatusCode},
    response::Json as ResponseJson,
    routing::{get, post},
    Router,
};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::fs;

#[derive(Serialize, Deserialize)]
struct UrlRegistry {
    active_base_url: Option<String>,
    updated_at: String,
    #[serde(rename = "type")]
    url_type: String,
    invisible_ip: bool,
}

#[derive(Serialize, Deserialize)]
struct ConnectRequest {
    target_url: String,
    save_to_registry: Option<bool>,
}

#[derive(Serialize)]
struct ApiResponse {
    status: String,
    host: String,
    full_url: String,
    invisible_hosting: bool,
    timestamp: String,
}

#[derive(Serialize)]
struct ConnectionResponse {
    status: String,
    target_url: String,
    current_host: String,
    current_url: String,
    connection_type: String,
    invisible: bool,
    timestamp: String,
}

// Load URL registry
async fn load_url_registry() -> Option<UrlRegistry> {
    if let Ok(content) = fs::read_to_string("config/url-registry.json").await {
        serde_json::from_str(&content).ok()
    } else {
        None
    }
}

// Get current timestamp
fn get_timestamp() -> String {
    chrono::Utc::now().to_rfc3339()
}

// Main index endpoint
async fn index(Host(host): Host, headers: HeaderMap) -> ResponseJson<serde_json::Value> {
    let registry = load_url_registry().await;
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") 
        || host.contains("trycloudflare") {
        "https"
    } else {
        "http"
    };
    let full_url = format!("{}://{}", scheme, host);

    ResponseJson(serde_json::json!({
        "message": "EU-UNION-AI-PACT Rust API Active",
        "current_host": host,
        "full_url": full_url,
        "registry_url": registry.as_ref().and_then(|r| r.active_base_url.clone()),
        "invisible_hosting": true,
        "timestamp": get_timestamp(),
        "registry_info": registry
    }))
}

// Health check
async fn health(Host(host): Host, headers: HeaderMap) -> ResponseJson<ApiResponse> {
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") {
        "https"
    } else {
        "http"
    };
    let full_url = format!("{}://{}", scheme, host);

    ResponseJson(ApiResponse {
        status: "healthy".to_string(),
        host,
        full_url,
        invisible_hosting: true,
        timestamp: get_timestamp(),
    })
}

// TrailStar connection endpoint
async fn api_connect(
    Host(host): Host,
    headers: HeaderMap,
    Json(payload): Json<ConnectRequest>
) -> Result<ResponseJson<ConnectionResponse>, StatusCode> {
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") {
        "https"
    } else {
        "http"
    };
    let current_url = format!("{}://{}", scheme, host);

    let connection = ConnectionResponse {
        status: "connected".to_string(),
        target_url: payload.target_url.clone(),
        current_host: host,
        current_url,
        connection_type: "trailstar".to_string(),
        invisible: true,
        timestamp: get_timestamp(),
    };

    // Save to registry if requested
    if payload.save_to_registry.unwrap_or(false) {
        if let Err(_) = fs::create_dir_all("config").await {
            return Err(StatusCode::INTERNAL_SERVER_ERROR);
        }

        let json = serde_json::to_string_pretty(&connection)
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

        if let Err(_) = fs::write("config/connections.json", json).await {
            return Err(StatusCode::INTERNAL_SERVER_ERROR);
        }
    }

    Ok(ResponseJson(connection))
}

// Chat endpoint
async fn chat_endpoint(
    Host(host): Host,
    headers: HeaderMap,
    Json(payload): Json<HashMap<String, serde_json::Value>>
) -> ResponseJson<serde_json::Value> {
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") {
        "https"
    } else {
        "http"
    };
    let full_url = format!("{}://{}", scheme, host);

    let message = payload.get("message")
        .and_then(|v| v.as_str())
        .unwrap_or("");

    ResponseJson(serde_json::json!({
        "response": format!("Rust API received: {}", message),
        "host": host,
        "base_url": full_url,
        "invisible_hosting": true,
        "tools_available": ["open_data_search", "code_healing", "sandbox_execute"],
        "timestamp": get_timestamp()
    }))
}

// Deploy endpoint
async fn deploy_endpoint(
    Host(host): Host,
    headers: HeaderMap,
    Json(payload): Json<HashMap<String, serde_json::Value>>
) -> ResponseJson<serde_json::Value> {
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") {
        "https"
    } else {
        "http"
    };
    let full_url = format!("{}://{}", scheme, host);

    let deployment_type = payload.get("type")
        .and_then(|v| v.as_str())
        .unwrap_or("automatic");

    ResponseJson(serde_json::json!({
        "status": "deployed",
        "deployment_url": full_url,
        "invisible_ip": true,
        "deployment_type": deployment_type,
        "timestamp": get_timestamp(),
        "endpoints": {
            "main": full_url,
            "api": format!("{}/api", full_url),
            "health": format!("{}/health", full_url),
            "connect": format!("{}/api/connect", full_url)
        }
    }))
}

// Show registry
async fn show_registry(Host(host): Host, headers: HeaderMap) -> ResponseJson<serde_json::Value> {
    let registry = load_url_registry().await;
    let scheme = if headers.get("x-forwarded-proto").is_some() 
        || host.contains("cloudflare") {
        "https"
    } else {
        "http"
    };
    let full_url = format!("{}://{}", scheme, host);

    let mut header_map = HashMap::new();
    for (name, value) in headers.iter() {
        if let Ok(value_str) = value.to_str() {
            header_map.insert(name.to_string(), value_str.to_string());
        }
    }

    ResponseJson(serde_json::json!({
        "registry": registry,
        "current_request": {
            "host": host,
            "url": full_url,
            "headers": header_map
        }
    }))
}

#[tokio::main]
async fn main() {
    println!("🚀 Starting EU-UNION-AI-PACT Rust API");

    // Load registry on startup
    if let Some(registry) = load_url_registry().await {
        println!("📍 Current base URL: {:?}", registry.active_base_url);
    }
    println!("🔗 TrailStar connection ready");

    let app = Router::new()
        .route("/", get(index))
        .route("/health", get(health))
        .route("/api/connect", post(api_connect))
        .route("/api/chat", post(chat_endpoint))
        .route("/api/deploy", post(deploy_endpoint))
        .route("/registry", get(show_registry));

    let listener = tokio::net::TcpListener::bind("0.0.0.0:8000")
        .await
        .unwrap();

    println!("🌍 Server running on http://0.0.0.0:8000");
    println!("💡 Accepts any host header - ready for invisible hosting");

    axum::serve(listener, app).await.unwrap();
}

use anyhow::Result;
use axum::{routing::post, Router, Json};
use axum::http::HeaderMap;
use serde::{Deserialize, Serialize};
use std::{collections::HashMap, net::SocketAddr, sync::Arc};
use wasmtime::{Engine, Module, Store, Linker, Config, Val, ValType};
use parking_lot::RwLock;

#[derive(Deserialize)]
struct ValidationReq {
    #[serde(default)]
    validator: String,
    payload: serde_json::Value,
}

#[derive(Serialize)]
struct ValidationResp {
    result: serde_json::Value,
    validator: String,
    fuel_used: u64,
    compliance_score: i32,
}

struct ValidatorModules {
    engine: Engine,
    modules: RwLock<HashMap<String, Arc<Module>>>,
    base_dir: String,
    default_validator: String,
}

impl ValidatorModules {
    fn new(base_dir: String, default_validator: String) -> Result<Self> {
        let mut cfg = Config::new();
        cfg.consume_fuel(true);
        let engine = Engine::new(&cfg)?;
        Ok(Self {
            engine,
            modules: RwLock::new(HashMap::new()),
            base_dir,
            default_validator,
        })
    }

    fn module_for(&self, validator: &str) -> Result<Arc<Module>> {
        {
            if let Some(m) = self.modules.read().get(validator).cloned() {
                return Ok(m);
            }
        }
        let path = format!("{}/{}.wasm", self.base_dir, validator);
        let effective = if std::fs::metadata(&path).is_ok() {
            path
        } else {
            format!("{}/{}.wasm", self.base_dir, self.default_validator)
        };
        let module = Arc::new(Module::from_file(&self.engine, &effective)?);
        self.modules.write().insert(validator.to_string(), module.clone());
        Ok(module)
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let vm = Arc::new(ValidatorModules::new(
        "/runtime/validators".into(),
        "ai-validator".into(),
    )?);

    let app = Router::new()
        .route("/validate", post(validate))
        .route("/healthz", axum::routing::get(|| async { "OK" }))
        .with_state(vm.clone());

    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    println!("EU AI Pact Wasmtime Host listening on {addr}");
    axum::Server::bind(&addr).serve(app.into_make_service()).await?;
    Ok(())
}

async fn validate(
    axum::extract::State(vm): axum::extract::State<Arc<ValidatorModules>>,
    headers: HeaderMap,
    Json(req): Json<ValidationReq>,
) -> Result<Json<ValidationResp>, axum::http::StatusCode> {
    let validator = if !req.validator.is_empty() { 
        req.validator.clone() 
    } else { 
        "ai-validator".to_string() 
    };

    let module = vm.module_for(&validator)
        .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    let mut store = Store::new(&vm.engine, ());
    store.add_fuel(200_000).ok();

    let linker = Linker::new(&vm.engine);
    let instance = linker.instantiate(&mut store, &module)
        .map_err(|_| axum::http::StatusCode::BAD_REQUEST)?;

    let func = instance.get_func(&mut store, "validate_compliance")
        .ok_or(axum::http::StatusCode::BAD_REQUEST)?;

    // Erwartet (i32 input_length) -> (i32 compliance_score)
    let ty = func.ty(&store);
    if ty.params() != [ValType::I32] || ty.results() != [ValType::I32] {
        return Err(axum::http::StatusCode::BAD_REQUEST);
    }

    let json_str = req.payload.to_string();
    let len = json_str.len() as i32;

    let result = func.call(&mut store, &[Val::I32(len)])
        .map_err(|_| axum::http::StatusCode::INTERNAL_SERVER_ERROR)?;

    let compliance_score = match result[0] {
        Val::I32(v) => v,
        _ => 0
    };

    let fuel_used = store.fuel_consumed().unwrap_or(0);

    let mut result_payload = req.payload;
    result_payload["validation"] = serde_json::json!({
        "validator": validator,
        "compliance_score": compliance_score,
        "fuel_consumed": fuel_used,
        "eu_ai_act_compliant": compliance_score >= 80,
        "timestamp": chrono::Utc::now().to_rfc3339()
    });

    Ok(Json(ValidationResp { 
        result: result_payload, 
        validator, 
        fuel_used, 
        compliance_score 
    }))
}

/// EU AI Act Compliance Validator WASM Plugin
/// 
/// This WASM module validates AI systems against EU AI Act requirements.
/// Input: JSON payload length (simplified for demo)
/// Output: Compliance score (0-100)

#[no_mangle]
pub extern "C" fn validate_compliance(input_length: i32) -> i32 {
    // Simplified AI compliance scoring based on input characteristics
    // In real implementation, this would analyze the actual AI system properties

    let base_score = 70; // Base compliance score

    // Factor in data governance (longer descriptions generally indicate better documentation)
    let documentation_bonus = if input_length > 100 { 15 } else { 5 };

    // Risk assessment factor
    let risk_factor = if input_length > 500 { 10 } else { 0 };

    // Human oversight consideration (simplified heuristic)
    let oversight_bonus = if input_length > 200 { 5 } else { 0 };

    let final_score = base_score + documentation_bonus + risk_factor + oversight_bonus;

    // Cap at 100
    if final_score > 100 { 100 } else { final_score }
}

#[no_mangle]
pub extern "C" fn risk_category(system_type: i32) -> i32 {
    // Returns risk category according to EU AI Act
    // 0: Unacceptable risk
    // 1: High risk
    // 2: Limited risk  
    // 3: Minimal risk

    match system_type {
        0..=25 => 3,    // Minimal risk (basic AI systems)
        26..=50 => 2,   // Limited risk (general purpose AI)
        51..=75 => 1,   // High risk (critical applications)
        _ => 0,         // Unacceptable risk (prohibited applications)
    }
}

#[no_mangle]
pub extern "C" fn transparency_requirement(risk_level: i32) -> i32 {
    // Returns transparency requirements level (0-5)
    match risk_level {
        0 => 0, // Prohibited - no transparency can make it acceptable
        1 => 5, // High risk - maximum transparency required
        2 => 3, // Limited risk - moderate transparency
        3 => 1, // Minimal risk - basic transparency
        _ => 1,
    }
}

#!/usr/bin/env python3
"""FORINA Offline Trust-Policy Starter (no network, no DNS writes, no certification)."""
import argparse
import datetime as dt
import json
import pathlib
import secrets
import sys
from urllib.parse import urlsplit
HERE = pathlib.Path(__file__).resolve().parent
EU_BASE = ['GDPR','EU_AI_ACT','NIS2','DORA','EIDAS','MICA','PSD2','DSA','DMA','EU_FOI']

def load(name):
    return json.loads((HERE/name).read_text(encoding='utf-8'))

def hostname(raw):
    if not raw or any(c in raw for c in '\r\n\t '):
        raise ValueError('Leere oder ungültige Domain')
    u=urlsplit(raw if '://' in raw else 'https://'+raw)
    if u.scheme not in ('https','http') or u.username or u.password:
        raise ValueError('Nur http/https URLs ohne Zugangsdaten')
    if u.port is not None:
        raise ValueError('URLs mit Ports sind für die Domainkontrolle nicht unterstützt')
    host = u.hostname
    if not host:
        raise ValueError('Domain fehlt')
    try:
        host=host.rstrip('.').encode('idna').decode('ascii').lower()
    except UnicodeError:
        raise ValueError('Domain-IDN ungültig')
    labels=host.split('.')
    if len(host)>253 or len(labels)<2 or any(not (1<=len(x)<=63 and x[0].isalnum() and x[-1].isalnum() and all(y.isalnum() or y=='-' for y in x)) for x in labels):
        raise ValueError('Ungültiger DNS-Hostname')
    if all(x.isdigit() for x in labels) or host in ('localhost.localdomain','local.internal'):
        raise ValueError('IP und lokale Namen sind ausgeschlossen')
    return host

def run_catalog(args):
    countries,laws=load('jurisdictions.json'),load('laws.json')
    codes=[v.upper() for v in args.jurisdiction] if args.jurisdiction else sorted(countries)
    for code in codes:
        if code not in countries:
            raise ValueError('Unbekannter Rechtsraum '+code)
    result={'mode':'OFFLINE_CATALOG','jurisdictions':{c:countries[c] for c in codes},'regulations':laws if args.all_laws else None,
            'legal_effect':'NONE','message':'Informationskatalog: keine Rechtsberatung oder Zulassungsprüfung.'}
    if args.us_states:
        result['us_states']=load('us_states.json')
    print(json.dumps(result,ensure_ascii=False,indent=2))

def run_plan(args):
    countries,laws=load('jurisdictions.json'),load('laws.json')
    codes=[c.upper() for c in args.jurisdiction]
    for c in codes:
        if c not in countries: raise ValueError('Unbekannter Rechtsraum: '+c)
    hosts=[hostname(x) for x in args.domain]
    # Never infer geography or organizational identity from a TLD or hostname alone.
    possible=set()
    for c in codes:
        for key in countries[c]['national_compliance_topics']:
            if key=='EU_BASE': possible.update(EU_BASE)
            else: possible.add(key)
    sector_extra={'finance':['DORA','PSD2','US_GLBA','CH_FINMA','SG_MAS'],
                  'critical':['NIS2'], 'crypto':['MICA'], 'platform':['DSA','DMA'],
                  'ai':['EU_AI_ACT'],'government':['EU_FOI','US_FOIA','US_SUNSHINE'], 'general':[]}
    for k in sector_extra[args.sector]:
        if k in laws and any(x in codes for x in ['EU','DE','IE','ES','IT','FR','BE','LU','PT','SE','FI','DK']) and k in ('DORA','PSD2','MICA','NIS2','DSA','DMA','EU_AI_ACT','EU_FOI'):
            possible.add(k)
        if 'US' in codes and k.startswith('US_'): possible.add(k)
        if 'CH' in codes and k.startswith('CH_'): possible.add(k)
        if 'SG' in codes and k.startswith('SG_'): possible.add(k)
    selected={k:laws[k] for k in sorted(possible) if k in laws}
    controls=['AUTHORIZATION_REQUIRED','DOMAIN_CONTROL_UNVERIFIED','ORG_IDENTITY_UNVERIFIED',
              'REGULATORY_SCOPE_NOT_ASSESSED','NO_CERTIFICATION','NO_NETWORK','NO_DNS_WRITE','NO_API_ACCESS']
    out={'mode':'LOCAL_DRY_RUN','created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),
         'hosts':[{'hostname':h,'status':'UNVERIFIED','federation_status':'NOT_ENROLLED'} for h in hosts],
         'jurisdictions':codes,'sector':args.sector,'possible_regulations':selected,
         'guardrails':controls,'decision':'REVIEW_REQUIRED','access_granted':False,
         'explanation':'Gesetze sind Prüfkandidaten und KEINE festgestellte Rechtsanwendbarkeit.'}
    if 'US' in codes and args.us_state:
        states=load('us_states.json')
        for st in args.us_state:
            if st not in states: raise ValueError('US-Bundesstaat unbekannt: '+st)
        out['us_states']={st:states[st] for st in args.us_state}
    print(json.dumps(out,ensure_ascii=False,indent=2))

def run_challenge(args):
    host=hostname(args.domain)
    if not args.authorization_reference or len(args.authorization_reference.strip())<8:
        raise ValueError('Dokumentierte Freigabereferenz erforderlich (mindestens 8 Zeichen)')
    token=secrets.token_urlsafe(32)
    # Custom, non-ACME TXT proof; NEVER use _acme-challenge to avoid affecting real CAs.
    print(json.dumps({'protocol':'FORINA-DEMO-DNS-TXT-v0.1','domain':host,
       'txt_name':'_forina-challenge.'+host,
       'txt_value':'forina-v1='+token,'ttl_suggested_seconds':300,
       'authorization_reference':args.authorization_reference,
       'challenge_created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),
       'max_age_seconds':900,
       'status':'PENDING_EXTERNAL_DNS_VERIFICATION','domain_control_verified':False,
       'organizational_identity_verified':False,'federation_access_granted':False,
       'warning':'Keine DNS-Abfrage, kein DNS-Write, kein Zertifikat, keine Rechtszertifizierung. '
                 'Freigabereferenz ist selbst kein überprüfter Zustimmungsnachweis.'},ensure_ascii=False,indent=2))

def main():
    p=argparse.ArgumentParser(description=__doc__)
    sub=p.add_subparsers(dest='command',required=True)
    a=sub.add_parser('catalog',help='Rechtsräume und offizielle Portale lokal anzeigen')
    a.add_argument('-j','--jurisdiction',nargs='*',default=[])
    a.add_argument('--all-laws',action='store_true')
    a.add_argument('--us-states',action='store_true')
    a.set_defaults(fn=run_catalog)
    a=sub.add_parser('plan',help='Offline-Compliance-Prüfplan für URLs erzeugen')
    a.add_argument('-j','--jurisdiction',required=True,nargs='+')
    a.add_argument('--domain',required=True,nargs='+')
    a.add_argument('--sector',choices=['general','finance','critical','crypto','platform','ai','government'],default='general')
    a.add_argument('--us-state',action='append',default=[])
    a.set_defaults(fn=run_plan)
    a=sub.add_parser('challenge',help='Nur TXT-Nachtragsvorschlag für bereits autorisierte Domain erzeugen')
    a.add_argument('--domain',required=True)
    a.add_argument('--authorization-reference',required=True)
    a.set_defaults(fn=run_challenge)
    args=p.parse_args()
    try: args.fn(args)
    except (ValueError,OSError,json.JSONDecodeError) as ex:
        print('FORINA SAFETY STOP: '+str(ex),file=sys.stderr)
        return 2
    return 0
if __name__=='__main__':
    sys.exit(main())

