import sys, pathlib, unittest, io, json, contextlib
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parents[1]))
import forina
class ForinaTests(unittest.TestCase):
 def test_host(self):
  self.assertEqual(forina.hostname('https://example.org/path?x=1'),'example.org')
 def test_reject_credentials(self):
  with self.assertRaises(ValueError):forina.hostname('https://a:b@example.org')
 def test_reject_port(self):
  with self.assertRaises(ValueError):forina.hostname('https://example.org:8080/')
 def test_invalid(self):
  with self.assertRaises(ValueError):forina.hostname('https://localhost/')
 def test_all_states(self):
  self.assertEqual(len(forina.load('us_states.json')),50)
 def test_no_certificate(self):
  o=io.StringIO()
  with contextlib.redirect_stdout(o):
   forina.run_challenge(type('Args',(),{'domain':'example.org','authorization_reference':'APPROVAL-2026-1'})())
  data=json.loads(o.getvalue())
  self.assertFalse(data['domain_control_verified'])
  self.assertFalse(data['federation_access_granted'])
  self.assertEqual(data['status'],'PENDING_EXTERNAL_DNS_VERIFICATION')
 def test_plan_review_only(self):
  o=io.StringIO()
  a=type('Args',(),{'jurisdiction':['EU','US'],'sector':'finance','domain':['example.org'],'us_state':['California']})()
  with contextlib.redirect_stdout(o):forina.run_plan(a)
  data=json.loads(o.getvalue())
  self.assertFalse(data['access_granted'])
  self.assertEqual(data['decision'],'REVIEW_REQUIRED')
if __name__=='__main__':unittest.main()

