    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Schiedsgerichtsbarkeit | StarLightMovemenTz Foundation</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700;900&family=Montserrat:wght@200;300;400;600;700&display=swap');

        :root {
            --gold: #bf953f;
            --gold-light: #fcf6ba;
            --gold-mid: #b38728;
            --deep-dark: rgba(0, 8, 20, 0.98);
            --border-gold: linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fcf6ba, #bf953f);
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            min-height: 100vh;
            background-color: #000;
            color: #f0f0f0;
            font-family: 'Montserrat', sans-serif;
            overflow-x: hidden;
            overflow-y: auto;
            scroll-behavior: smooth;
        }

        #starfield {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
        }

        .content-wrapper {
            position: relative;
            z-index: 1000;
            max-width: 1400px;
            margin: 0 auto;
            padding: 80px 40px 100px;
        }

        .back-btn {
            position: fixed;
            top: 30px;
            left: 30px;
            padding: 12px 30px;
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.25) 0%, rgba(191, 149, 63, 0.35) 100%);
            border: 2px solid rgba(191, 149, 63, 0.6);
            color: #fcf6ba;
            font-family: 'Cinzel', serif;
            text-decoration: none;
            text-transform: uppercase;
            letter-spacing: 3px;
