        const canvas = document.getElementById('starCanvas');
        const ctx = canvas.getContext('2d');

        let width, height, stars = [];
        // ANZAHL DER STERNE: Simulation von massiver Dichte
        const starCount = 5000;

        function init() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width;
            canvas.height = height;
            stars = [];
            for (let i = 0; i < starCount; i++) {
                stars.push({
                    x: Math.random() * width - width / 2,
                    y: Math.random() * height - height / 2,
                    z: Math.random() * width,
                    o: Math.random(),
                    color: i % 15 === 0 ? "#fcf6ba" : "#ffffff" // Goldene Akzente alle paar Sterne
                });
            }
        }

        function draw() {
            // Schwarzer Hintergrund mit Motion Blur (Trail)
            ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
            ctx.fillRect(0, 0, width, height);

            ctx.save();
            ctx.translate(width / 2, height / 2);

            for (let i = 0; i < starCount; i++) {
                let star = stars[i];
                star.z -= 4.5; // Geschwindigkeit des Warp-Effekts

                // Wenn der Stern am Betrachter vorbei ist, hinten neu spawnen
                if (star.z <= 0) {
                    star.z = width;
                    star.x = Math.random() * width - width / 2;
                    star.y = Math.random() * height - height / 2;
                }

                // Perspektivische Berechnung der Position
                const x = star.x * (width / star.z);
                const y = star.y * (height / star.z);
                const s = Math.min(2, 1.5 * (width / star.z)); // Größe basierend auf Distanz

                // Zeichne Stern
                ctx.beginPath();
                ctx.fillStyle = star.color;
                ctx.globalAlpha = star.o * (1 - star.z / width); // Einblenden wenn sie näher kommen

                ctx.arc(x, y, s / 2, 0, Math.PI * 2);
                ctx.fill();
                ctx.globalAlpha = 1;
            }
            ctx.restore();
            requestAnimationFrame(draw);
        }

        // Anpassung bei Fenstergröße-Änderung
        window.addEventListener('resize', init);

        // Start der Engine
        init();
        draw();
    </script>

