// Frontend Failover Logic
const SUPABASE_URLS = [
    'https://xblewwjjqvwerypvttfh.supabase.co', // Primary
    'https://xblewwjjqvwerypvttfh-eu-west-1.supabase.co', // Replica 1
    'https://xblewwjjqvwerypvttfh-us-east-1.supabase.co'  // Replica 2
