async function createSupabaseClientWithFailover() {
    for (let i = 0; i < SUPABASE_URLS.length; i++) {
        try {
            const client = supabase.createClient(
                SUPABASE_URLS[currentEndpointIndex],
                SUPABASE_ANON_KEY
            );

            // Health check
