### 9.3 Caching Strategy

```javascript
// Client-Side Cache mit Service Worker
// service-worker.js
const CACHE_NAME = 'urls-archive-v1';
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

self.addEventListener('fetch', (event) => {
    const url = new URL(event.request.url);

    // Only cache API requests
    if (url.hostname.includes('supabase.co')) {
        event.respondWith(
            caches.open(CACHE_NAME).then((cache) => {
                return cache.match(event.request).then((response) => {
                    if (response) {
                        const cachedTime = response.headers.get('sw-cached-time');
                        if (cachedTime && Date.now() - parseInt(cachedTime) < CACHE_DURATION) {
                            return response;
                        }
                    }

                    return fetch(event.request).then((response) => {
                        if (response.ok) {
                            const responseClone = response.clone();
                            const headers = new Headers(responseClone.headers);
                            headers.append('sw-cached-time', Date.now().toString());

                            const cachedResponse = new Response(responseClone.body, {
                                status: responseClone.status,
                                statusText: responseClone.statusText,
                                headers: headers
                            });

                            cache.put(event.request, cachedResponse);
                        }
                        return response;
                    });
                });
            })
        );
    }
});

// Application-Level Cache
class CacheManager {
    constructor() {
        this.cache = new Map();
        this.cacheDuration = 5 * 60 * 1000; // 5 minutes
    }

    set(key, value) {
        this.cache.set(key, {
            value,
            timestamp: Date.now()
        });
    }

    get(key) {
        const item = this.cache.get(key);
        if (!item) return null;

        if (Date.now() - item.timestamp > this.cacheDuration) {
            this.cache.delete(key);
            return null;
        }

        return item.value;
    }

    invalidate(key) {
        this.cache.delete(key);
    }

    clear() {
        this.cache.clear();
    }
}

const cacheManager = new CacheManager();

// Usage in comment loading
async function loadCommentsWithCache(urlId) {
    const cacheKey = `comments_${urlId}`;
    const cached = cacheManager.get(cacheKey);

    if (cached) {
        return cached;
    }

    const { data, error } = await supabase
        .from('url_comments')
        .select('*')
        .eq('url_id', urlId);

    if (!error) {
        cacheManager.set(cacheKey, data);
    }

    return data;
}
