<!DOCTYPE html>
<html lang="de">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Schiedsgerichtsbarkeit | StarLightMovemenTz Foundation</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700;900&family=Montserrat:wght@200;300;400;600;700&display=swap');

        :root {
            --gold: #bf953f;
            --gold-light: #fcf6ba;
            --gold-mid: #b38728;
            --deep-dark: rgba(0, 8, 20, 0.98);
            --border-gold: linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fcf6ba, #bf953f);
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            min-height: 100vh;
            background-color: #000;
            color: #f0f0f0;
            font-family: 'Montserrat', sans-serif;
            overflow-x: hidden;
            overflow-y: auto;
            scroll-behavior: smooth;
        }

        #starfield {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
        }

        .content-wrapper {
            position: relative;
            z-index: 1000;
            max-width: 1400px;
            margin: 0 auto;
            padding: 80px 40px 100px;
        }

        .back-btn {
            position: fixed;
            top: 30px;
            left: 30px;
            padding: 12px 30px;
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.25) 0%, rgba(191, 149, 63, 0.35) 100%);
            border: 2px solid rgba(191, 149, 63, 0.6);
            color: #fcf6ba;
            font-family: 'Cinzel', serif;
            text-decoration: none;
            text-transform: uppercase;
            letter-spacing: 3px;
            font-size: 0.8rem;
            font-weight: 600;
            backdrop-filter: blur(25px) saturate(150%);
            -webkit-backdrop-filter: blur(25px) saturate(150%);
            transition: all 0.4s ease;
            z-index: 10000;
            cursor: pointer;
            border-radius: 8px;
            box-shadow: 0 4px 16px 0 rgba(0, 0, 0, 0.3);
        }

        .back-btn:hover {
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.9) 0%, rgba(252, 246, 186, 0.9) 100%);
            color: #000;
            box-shadow: 0 8px 32px 0 rgba(191, 149, 63, 0.5), 0 0 40px rgba(191, 149, 63, 0.6);
            transform: translateX(-5px);
        }

        .header {
            text-align: center;
            margin-bottom: 80px;
        }

        .header h1 {
            font-family: 'Cinzel', serif;
            font-size: clamp(2rem, 8vw, 4rem);
            background: var(--border-gold);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin: 0 0 20px 0;
            letter-spacing: 10px;
            text-transform: uppercase;
        }

        .header p {
            font-size: 1.2rem;
            color: var(--gold-light);
            letter-spacing: 4px;
            text-transform: uppercase;
            font-weight: 300;
        }

        .glass-card {
            background: linear-gradient(135deg, rgba(0, 8, 20, 0.75) 0%, rgba(0, 8, 20, 0.85) 100%);
            border: 2px solid rgba(191, 149, 63, 0.6);
            padding: 50px;
            margin-bottom: 50px;
            backdrop-filter: blur(60px) saturate(180%);
            -webkit-backdrop-filter: blur(60px) saturate(180%);
            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37), 0 0 100px rgba(191, 149, 63, 0.15);
            border-radius: 12px;
            position: relative;
            overflow: hidden;
        }

        .glass-card::after {
            content: "";
            position: absolute;
            top: -150%;
            left: -150%;
            width: 300%;
            height: 300%;
            background: linear-gradient(45deg, transparent 45%, rgba(252, 246, 186, 0.03) 48%, rgba(252, 246, 186, 0.06) 50%, rgba(252, 246, 186, 0.03) 52%, transparent 55%);
            animation: shine 8s infinite linear;
        }

        @keyframes shine {
            0% { transform: translate(-20%, -20%); }
            100% { transform: translate(20%, 20%); }
        }

        h2 {
            font-family: 'Cinzel', serif;
            color: var(--gold);
            font-size: 2rem;
            margin: 0 0 30px 0;
            letter-spacing: 5px;
            text-transform: uppercase;
            border-bottom: 2px solid rgba(191, 149, 63, 0.3);
            padding-bottom: 20px;
        }

        h3 {
            font-family: 'Cinzel', serif;
            color: var(--gold-light);
            font-size: 1.3rem;
            margin: 30px 0 15px 0;
            letter-spacing: 3px;
            border-left: 4px solid var(--gold);
            padding-left: 20px;
        }

        .institutions-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 30px;
            margin: 40px 0;
        }

        .institution-card {
            background: linear-gradient(135deg, rgba(255,255,255,0.03) 0%, rgba(255,255,255,0.05) 100%);
            border: 1px solid rgba(191, 149, 63, 0.5);
            padding: 35px;
            backdrop-filter: blur(10px);
            border-radius: 8px;
            transition: all 0.4s ease;
            text-align: center;
        }

        .institution-card:hover {
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.12) 0%, rgba(191, 149, 63, 0.15) 100%);
            border-color: var(--gold);
            transform: translateY(-10px);
            box-shadow: 0 8px 32px 0 rgba(191, 149, 63, 0.3);
        }

        .flag {
            font-size: 4rem;
            margin-bottom: 20px;
        }

        .institution-card h4 {
            font-family: 'Cinzel', serif;
            color: var(--gold-light);
            font-size: 1.2rem;
            margin: 15px 0;
            letter-spacing: 2px;
        }

        .institution-card p {
            color: #ccc;
            line-height: 1.8;
            margin-bottom: 20px;
        }

        .variant-box {
            background: linear-gradient(135deg, rgba(0, 8, 20, 0.6) 0%, rgba(0, 8, 20, 0.7) 100%);
            border: 1px solid rgba(191, 149, 63, 0.4);
            border-left: 4px solid var(--gold);
            padding: 30px;
            margin: 25px 0;
            backdrop-filter: blur(20px);
            border-radius: 8px;
        }

        .variant-number {
            display: inline-block;
            background: var(--border-gold);
            color: #000;
            font-family: 'Cinzel', serif;
            font-weight: 900;
            padding: 5px 15px;
            border-radius: 20px;
            font-size: 0.9rem;
            letter-spacing: 2px;
            margin-bottom: 15px;
        }

        .variant-title {
            font-family: 'Cinzel', serif;
            color: var(--gold-light);
            font-size: 1.4rem;
            margin: 10px 0;
            letter-spacing: 2px;
        }

        .clause-text {
            background: rgba(0, 0, 0, 0.5);
            border: 1px solid rgba(191, 149, 63, 0.3);
            padding: 25px;
            margin: 20px 0;
            font-family: 'Courier New', monospace;
            font-size: 0.95rem;
            line-height: 1.9;
            color: #fcf6ba;
            border-radius: 6px;
            font-style: italic;
        }

        .check-icon {
            color: #00ff88;
            margin-right: 10px;
        }

        .btn-link {
            display: inline-block;
            padding: 12px 30px;
            border: 2px solid rgba(191, 149, 63, 0.6);
            background: linear-gradient(135deg, rgba(0, 8, 20, 0.65) 0%, rgba(0, 8, 20, 0.75) 100%);
            color: var(--gold-light);
            font-family: 'Cinzel', serif;
            text-decoration: none;
            letter-spacing: 2px;
            text-transform: uppercase;
            font-size: 0.85rem;
            font-weight: 600;
            transition: all 0.4s ease;
            backdrop-filter: blur(20px);
            border-radius: 6px;
            margin: 10px 5px;
        }

        .btn-link:hover {
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.9) 0%, rgba(252, 246, 186, 0.9) 100%);
            color: #000;
            box-shadow: 0 8px 32px 0 rgba(191, 149, 63, 0.5);
            transform: translateY(-3px);
        }

        .note-box {
            background: linear-gradient(135deg, rgba(191, 149, 63, 0.1) 0%, rgba(191, 149, 63, 0.15) 100%);
            border: 2px dashed rgba(191, 149, 63, 0.5);
            padding: 30px;
            margin: 40px 0;
            border-radius: 8px;
            backdrop-filter: blur(20px);
        }

        .note-box strong {
            color: var(--gold-light);
            font-size: 1.1rem;
            letter-spacing: 2px;
        }

        ul {
            list-style: none;
            padding-left: 0;
        }

        ul li {
            padding: 10px 0 10px 30px;
            position: relative;
            line-height: 1.8;
        }

        ul li::before {
            content: "⚖️";
            position: absolute;
            left: 0;
        }

        @media (max-width: 768px) {
            .content-wrapper {
                padding: 100px 20px 60px;
            }

            .glass-card {
                padding: 30px;
            }

            .institutions-grid {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
