<script>
    const bgCanvas = document.getElementById('bg-canvas');
    const cardCanvas = document.getElementById('card-canvas');
    const bgCtx = bgCanvas.getContext('2d');
    const cardCtx = cardCanvas.getContext('2d');

    class HarmonicGeometry {
        constructor(canvas, ctx, starCount, connectionDist, speedMult) {
            this.canvas = canvas;
            this.ctx = ctx;
            this.starCount = starCount;
            this.connectionDist = connectionDist;
            this.speedMult = speedMult || 1;
            this.points = [];
            this.init();
        }

        init() {
            this.canvas.width = this.canvas.offsetWidth || window.innerWidth;
            this.canvas.height = this.canvas.offsetHeight || window.innerHeight;
            this.points = [];
            for (let i = 0; i < this.starCount; i++) {
                this.points.push({
                    x: Math.random() * this.canvas.width,
                    y: Math.random() * this.canvas.height,
                    size: Math.random() * 2,
                    vx: (Math.random() - 0.5) * 0.4 * this.speedMult,
                    vy: (Math.random() - 0.5) * 0.4 * this.speedMult,
                    opacity: Math.random()
                });
            }
        }

        draw() {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
            for(let i=0; i < this.points.length; i++) {
                let p = this.points[i];
                p.x += p.vx;
                p.y += p.vy;
                if(p.x < 0 || p.x > this.canvas.width) p.vx *= -1;
                if(p.y < 0 || p.y > this.canvas.height) p.vy *= -1;
                this.ctx.fillStyle = `rgba(255, 255, 255, ${p.opacity})`;
                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                this.ctx.fill();
                for(let j=i+1; j < this.points.length; j++) {
                    let p2 = this.points[j];
                    let dx = p.x - p2.x;
                    let dy = p.y - p2.y;
                    let dist = Math.sqrt(dx*dx + dy*dy);
                    if(dist < this.connectionDist) {
                        this.ctx.strokeStyle = `rgba(191, 149, 63, ${0.45 * (1 - dist/this.connectionDist)})`;
                        this.ctx.lineWidth = 0.6;
                        this.ctx.beginPath();
                        this.ctx.moveTo(p.x, p.y);
                        this.ctx.lineTo(p2.x, p2.y);
                        this.ctx.stroke();
                    }
                }
            }
        }
    }

    // Höhere Dichte: 800 Sterne im Hintergrund, 200 in der Karte
    const bgLogic = new HarmonicGeometry(bgCanvas, bgCtx, 800, 110, 1.2);
    const cardLogic = new HarmonicGeometry(cardCanvas, cardCtx, 200, 130, 0.8);

    function animate() {
        bgLogic.draw();
        cardLogic.draw();
        requestAnimationFrame(animate);
    }

    window.addEventListener('resize', () => {
        bgLogic.init();
        cardLogic.init();
    });

    window.onload = animate;
</script>

</body>
