#!/usr/bin/env node
// scripts/ghost-buster.js
// 🚨 Ghost Detection & Clean Code Enforcement System

import fs from 'fs';
import path from 'path';

// 🚫 FORBIDDEN PATTERNS (Ghost Detection Rules)
const FORBIDDEN_PATTERNS = [
    { pattern: /lovable\.dev/gi, name: 'Lovable.dev Reference' },
    { pattern: /hello-hug-wave/gi, name: 'Hello-Hug-Wave Project' },
    { pattern: /REPLACE_WITH_PROJECT_ID/gi, name: 'Placeholder ID' },
    { pattern: /onbiela\.dev/gi, name: 'Biela.dev Reference' },
    { pattern: /macaly-app\.com/gi, name: 'Macaly App Reference' },
    { pattern: /PLACEHOLDER/gi, name: 'Generic Placeholder' },
    { pattern: /TODO: FIX/gi, name: 'Unresolved TODO' }
];

// 📂 DIRECTORIES TO SCAN
const SCAN_TARGETS = [
    './urls-archive.html',
    './ENTERPRISE_ARCHITECTURE_COMPLETE.md',
    './ENTERPRISE_ARCHITECTURE.md',
    './ENTERPRISE_ARCHITECTURE_PART2.md',
    './ENTERPRISE_ARCHITECTURE_PART3.md',
    './URL_SYSTEM_STATUS.md',
    './SUPABASE_SETUP_GUIDE.md',
    './src'
];

// 🚫 IGNORE PATTERNS (Don't scan these)
const IGNORE_PATHS = [
    'node_modules',
    '.git',
    'dist',
    'build',
    '.next',
    'URL_ANALYSE',
    'ANALYSE_BERICHT',
    'URL_EXTRAKTION',
    'URL_TABELLE',
    'URL_LISTE',
    'ALLE_URLS'
];

console.log('\n🚀 Starting Ghost-Buster: Scanning for unauthorized references...\n');

let ghostCount = 0;
let filesScanned = 0;
const ghostFindings = [];

/**
 * Scan a single file for ghost patterns
 */
function scanFile(filePath) {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');
        let fileHasGhost = false;

        FORBIDDEN_PATTERNS.forEach(({ pattern, name }) => {
            lines.forEach((line, lineNumber) => {
                if (pattern.test(line)) {
                    ghostCount++;
                    fileHasGhost = true;

                    const finding = {
                        file: filePath,
                        line: lineNumber + 1,
                        pattern: name,
                        content: line.trim().substring(0, 80)
                    };

                    ghostFindings.push(finding);

                    console.error(`⚠️  GHOST DETECTED!`);
                    console.error(`   📄 File: ${filePath}`);
                    console.error(`   📍 Line: ${lineNumber + 1}`);
                    console.error(`   👻 Pattern: ${name}`);
                    console.error(`   💬 Content: ${line.trim().substring(0, 80)}...`);
                    console.error('');
                }
            });
        });

        if (!fileHasGhost) {
            filesScanned++;
        }
    } catch (error) {
        console.warn(`⚠️  Could not read file: ${filePath} - ${error.message}`);
    }
}

/**
 * Check if path should be ignored
 */
function shouldIgnore(fullPath) {
    return IGNORE_PATHS.some(ignorePath => fullPath.includes(ignorePath));
}

/**
 * Recursively walk directory
 */
function walkDir(dir) {
    if (!fs.existsSync(dir)) {
        console.warn(`⚠️  Directory not found: ${dir}`);
        return;
    }

    const items = fs.readdirSync(dir);

    items.forEach(item => {
        const fullPath = path.join(dir, item);

        if (shouldIgnore(fullPath)) {
            return;
        }

        try {
            const stat = fs.lstatSync(fullPath);

            if (stat.isDirectory()) {
                walkDir(fullPath);
            } else if (stat.isFile()) {
                // Only scan relevant file types
                if (/\.(ts|tsx|js|jsx|md|html|json|sql)$/.test(fullPath)) {
                    scanFile(fullPath);
                }
            }
        } catch (error) {
            console.warn(`⚠️  Error accessing: ${fullPath}`);
        }
    });
}

/**
 * Main execution
 */
SCAN_TARGETS.forEach(target => {
    if (fs.existsSync(target)) {
        const stat = fs.lstatSync(target);

        if (stat.isDirectory()) {
            console.log(`📂 Scanning directory: ${target}`);
            walkDir(target);
        } else {
            console.log(`📄 Scanning file: ${target}`);
            scanFile(target);
        }
    } else {
        console.warn(`⚠️  Target not found: ${target}`);
    }
});

// 📊 FINAL REPORT
console.log('\n' + '═'.repeat(70));
console.log('📊 GHOST-BUSTER SCAN COMPLETE');
console.log('═'.repeat(70));
console.log(`✅ Files scanned (clean): ${filesScanned}`);
console.log(`👻 Ghost references found: ${ghostCount}`);
console.log('═'.repeat(70) + '\n');

if (ghostCount === 0) {
    console.log('✅ ✅ ✅ SYSTEM CLEAN: No ghosts or unauthorized references found!');
    console.log('🎉 Your codebase follows the Single Source of Truth principle!\n');
    process.exit(0);
} else {
    console.log('❌ ❌ ❌ GHOSTS DETECTED: System requires cleanup!');
    console.log('\n📋 Summary by Pattern:\n');

    // Group findings by pattern
    const grouped = {};
    ghostFindings.forEach(finding => {
        if (!grouped[finding.pattern]) {
            grouped[finding.pattern] = [];
        }
        grouped[finding.pattern].push(finding);
    });

    Object.entries(grouped).forEach(([pattern, findings]) => {
        console.log(`   👻 ${pattern}: ${findings.length} occurrence(s)`);
    });

    console.log('\n💡 Action Required:');
    console.log('   1. Review the findings above');
    console.log('   2. Replace ghost references with official URLs from project-constants.ts');
    console.log('   3. Remove placeholder IDs and TODOs');
    console.log('   4. Re-run this script to verify cleanup\n');

    process.exit(1);
}

// scripts/log-aggregator.js
// 📊 Log-Aggregator für das Monitoring-Dashboard
// Sammelt Logs aus verschiedenen Quellen und bereitet sie für die UI auf

const fs = require('fs');
const path = require('path');
const chalk = require('chalk');

// Konfiguration
const LOG_SOURCES = [
  { path: './logs/deployment.log', type: 'deployment' },
  { path: './logs/monitoring.log', type: 'monitoring' },
  { path: './logs/security.log', type: 'security' },
  { path: './logs/ghost-buster.log', type: 'ghost-buster' },
];

const OUTPUT_FILE = './logs/aggregated.json';
const MAX_ENTRIES = 100;

// Log-Level Mapping
const LOG_LEVELS = {
  error: { icon: '❌', color: 'red', weight: 4 },
  warning: { icon: '⚠️', color: 'yellow', weight: 3 },
  info: { icon: '📊', color: 'cyan', weight: 2 },
  success: { icon: '✅', color: 'green', weight: 1 },
};

console.log(chalk.cyan.bold('\n📊 LOG-AGGREGATOR GESTARTET\n'));

// Log-Eintrag parsen
function parseLogLine(line, source) {
  // Beispiel-Format: [2026-02-17T09:30:45.123Z] [INFO] Message here
  const timestampRegex = /\[([\d-T:.Z]+)\]/;
  const levelRegex = /\[(ERROR|WARNING|INFO|SUCCESS)\]/i;

  const timestampMatch = line.match(timestampRegex);
  const levelMatch = line.match(levelRegex);

  if (!timestampMatch || !levelMatch) {
    return null;
  }

  const timestamp = timestampMatch[1];
  const level = levelMatch[1].toLowerCase();
  const message = line
    .replace(timestampRegex, '')
    .replace(levelRegex, '')
    .trim();

  return {
    timestamp,
    level,
    message,
    source: source.type,
    ...LOG_LEVELS[level],
  };
}

// Einzelne Log-Datei lesen
function readLogFile(source) {
  try {
    if (!fs.existsSync(source.path)) {
      console.log(chalk.gray(`   ⊗ ${source.path} nicht gefunden`));
      return [];
    }

    const content = fs.readFileSync(source.path, 'utf-8');
    const lines = content.split('\n').filter(l => l.trim());

    const entries = lines
      .map(line => parseLogLine(line, source))
      .filter(entry => entry !== null);

    console.log(chalk.green(`   ✓ ${source.type}: ${entries.length} Einträge`));

    return entries;
  } catch (error) {
    console.error(chalk.red(`   ✗ Fehler bei ${source.type}:`), error.message);
    return [];
  }
}

// Alle Logs aggregieren
function aggregateLogs() {
  console.log(chalk.cyan('🔍 Lese Log-Dateien...\n'));

  let allEntries = [];

  LOG_SOURCES.forEach(source => {
    const entries = readLogFile(source);
    allEntries = allEntries.concat(entries);
  });

  // Nach Timestamp sortieren (neueste zuerst)
  allEntries.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  // Auf MAX_ENTRIES limitieren
  const limitedEntries = allEntries.slice(0, MAX_ENTRIES);

  return limitedEntries;
}

// Statistiken berechnen
function calculateStats(entries) {
  const stats = {
    total: entries.length,
    byLevel: {
      error: entries.filter(e => e.level === 'error').length,
      warning: entries.filter(e => e.level === 'warning').length,
      info: entries.filter(e => e.level === 'info').length,
      success: entries.filter(e => e.level === 'success').length,
    },
    bySource: {},
    lastUpdate: new Date().toISOString(),
  };

  // Count by source
  entries.forEach(entry => {
    if (!stats.bySource[entry.source]) {
      stats.bySource[entry.source] = 0;
    }
    stats.bySource[entry.source]++;
  });

  return stats;
}

// Output schreiben
function writeOutput(entries, stats) {
  const outputDir = path.dirname(OUTPUT_FILE);

  // Erstelle logs-Verzeichnis falls nicht vorhanden
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const output = {
    logs: entries,
    stats,
    generatedAt: new Date().toISOString(),
  };

  fs.writeFileSync(OUTPUT_FILE, JSON.stringify(output, null, 2), 'utf-8');

  console.log(chalk.green(`\n✅ Aggregierte Logs gespeichert: ${OUTPUT_FILE}`));
}

// Statistiken anzeigen
function printStats(stats) {
  console.log('\n' + chalk.magenta.bold('📊 STATISTIKEN:'));
  console.log(chalk.white(`   Total: ${stats.total} Einträge`));
  console.log(chalk.red(`   Errors: ${stats.byLevel.error}`));
  console.log(chalk.yellow(`   Warnings: ${stats.byLevel.warning}`));
  console.log(chalk.cyan(`   Info: ${stats.byLevel.info}`));
  console.log(chalk.green(`   Success: ${stats.byLevel.success}`));

  console.log('\n' + chalk.cyan('📂 Nach Quelle:'));
  Object.entries(stats.bySource).forEach(([source, count]) => {
    console.log(chalk.white(`   ${source}: ${count}`));
  });
}

// Mock-Logs erstellen (falls keine echten vorhanden)
function createMockLogs() {
  console.log(chalk.yellow('\n⚠️  Keine Log-Dateien gefunden. Erstelle Mock-Logs...\n'));

  const mockEntries = [
    {
      timestamp: new Date().toISOString(),
      level: 'success',
      message: 'System started successfully',
      source: 'deployment',
      icon: '✅',
      color: 'green',
      weight: 1,
    },
    {
      timestamp: new Date(Date.now() - 60000).toISOString(),
      level: 'info',
      message: 'Database connection established',
      source: 'monitoring',
      icon: '📊',
      color: 'cyan',
      weight: 2,
    },
    {
      timestamp: new Date(Date.now() - 120000).toISOString(),
      level: 'success',
      message: 'Ghost-Buster scan completed - No threats detected',
      source: 'ghost-buster',
      icon: '✅',
      color: 'green',
      weight: 1,
    },
    {
      timestamp: new Date(Date.now() - 180000).toISOString(),
      level: 'info',
      message: 'RLS policies activated (30+ rules)',
      source: 'security',
      icon: '📊',
      color: 'cyan',
      weight: 2,
    },
  ];

  return mockEntries;
}

// Hauptfunktion
function main() {
  try {
    let entries = aggregateLogs();

    // Falls keine Logs gefunden, Mock-Logs erstellen
    if (entries.length === 0) {
      entries = createMockLogs();
    }

    const stats = calculateStats(entries);

    writeOutput(entries, stats);
    printStats(stats);

    console.log('\n' + chalk.green.bold('✅ LOG-AGGREGATION ABGESCHLOSSEN\n'));

  } catch (error) {
    console.error(chalk.red('\n❌ FEHLER:'), error.message);
    process.exit(1);
  }
}

// Start
main();

