'use client';

import { motion } from 'framer-motion';
import { useSystemStatus } from '@/context/SystemStatusContext';
import { useEffect, useState } from 'react';

interface LogEntry {
  timestamp: string;
  level: 'info' | 'warning' | 'error' | 'success';
  message: string;
  source: string;
}

interface LogDashboardProps {
  logs?: any[];
  maxHeight?: number;
}

export default function LogDashboard({ logs: externalLogs, maxHeight = 500 }: LogDashboardProps) {
  const { metrics } = useSystemStatus();
  const [logs, setLogs] = useState<LogEntry[]>(externalLogs || []);
  const [currentTime, setCurrentTime] = useState<string>('--:--:--');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    setCurrentTime(new Date().toLocaleTimeString());

    const timeInterval = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString());
    }, 1000);

    return () => clearInterval(timeInterval);
  }, []);

  useEffect(() => {
    // Use external logs if provided
    if (externalLogs && externalLogs.length > 0) {
      setLogs(externalLogs.slice(0, 15));
      return;
    }

    // Simulate log updates
    const interval = setInterval(() => {
      const newLog: LogEntry = {
        timestamp: new Date().toISOString(),
        level: metrics.cpu > 80 ? 'warning' : 'info',
        message: `CPU: ${metrics.cpu.toFixed(1)}% | Connections: ${metrics.activeConnections} | Request Rate: ${metrics.requestRate.toFixed(0)}/s`,
        source: 'monitoring'
      };

      setLogs(prev => [newLog, ...prev].slice(0, 15)); // Keep last 15 logs
    }, 10000); // Every 10 seconds

    return () => clearInterval(interval);
  }, [metrics, externalLogs]);

  const getLevelColor = (level: LogEntry['level']) => {
    switch (level) {
      case 'error': return 'text-red-400';
      case 'warning': return 'text-amber-400';
      case 'success': return 'text-emerald-400';
      default: return 'text-cyan-400';
    }
  };

  const getLevelIcon = (level: LogEntry['level']) => {
    switch (level) {
      case 'error': return '❌';
      case 'warning': return '⚠️';
      case 'success': return '✅';
      default: return '📊';
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-black/80 p-6 rounded-2xl border border-white/10 backdrop-blur-md"
    >
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-3">
          <motion.div
            animate={{ 
              scale: [1, 1.2, 1],
              opacity: [0.5, 1, 0.5]
            }}
            transition={{ duration: 2, repeat: Infinity }}
            className="w-2 h-2 rounded-full bg-cyan-400"
          />
          <h2 className="text-cyan-400 font-mono text-sm tracking-widest uppercase">
            System Logs
          </h2>
        </div>
        <div className="text-[10px] text-gray-500 font-mono">
          Last Update: {currentTime}
        </div>
      </div>

      {/* System Status Cards */}
      <div className="grid grid-cols-3 gap-3 mb-6">
        <div className="bg-gray-900/50 p-3 rounded-lg border border-white/5">
          <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-1">CPU</div>
          <div className={`text-2xl font-bold ${metrics.cpu > 80 ? 'text-red-400' : 'text-cyan-400'}`}>
            {Math.round(metrics.cpu)}%
          </div>
        </div>
        <div className="bg-gray-900/50 p-3 rounded-lg border border-white/5">
          <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-1">Memory</div>
          <div className="text-2xl font-bold text-purple-400">
            {Math.round(metrics.memory)}%
          </div>
        </div>
        <div className="bg-gray-900/50 p-3 rounded-lg border border-white/5">
          <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-1">Status</div>
          <div className={`text-sm font-bold ${metrics.errorRate < 5 ? 'text-emerald-400' : 'text-red-400'}`}>
            {metrics.errorRate < 5 ? '🛡️ SECURED' : '⚠️ ALERT'}
          </div>
        </div>
      </div>

      {/* Log Entries */}
      <div className="space-y-2 font-mono text-[11px] max-h-64 overflow-y-auto custom-scrollbar">
        {logs.length === 0 ? (
          <div className="text-gray-600 text-center py-8 italic">
            Waiting for system events...
          </div>
        ) : (
          logs.map((log, i) => (
            <motion.div
              key={`${log.timestamp}-${i}`}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="bg-gray-900/30 p-2 rounded border border-white/5 hover:border-cyan-500/30 transition-colors"
            >
              <div className="flex items-start gap-2">
                <span className="text-lg leading-none">{getLevelIcon(log.level)}</span>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2 mb-1">
                    <span className={`uppercase tracking-wider ${getLevelColor(log.level)}`}>
                      [{log.source}]
                    </span>
                    <span className="text-gray-600 text-[9px]">
                      {mounted ? new Date(log.timestamp).toLocaleTimeString() : '--:--:--'}
                    </span>
                  </div>
                  <p className="text-gray-400 break-words">{log.message}</p>
                </div>
              </div>
            </motion.div>
          ))
        )}
      </div>
    </motion.div>
  );
}

'use client';

import React from 'react';
import { motion } from 'framer-motion';

interface MetricDisplayProps {
  label: string;
  value: number;
  unit: string;
  icon: React.ReactNode;
  threshold: number;
  isInverted?: boolean; // For error rate (high = bad)
}

export default function MetricDisplay({
  label,
  value,
  unit,
  icon,
  threshold,
  isInverted = false,
}: MetricDisplayProps) {
  // Determine status color
  const getStatusColor = () => {
    const isOverThreshold = value >= threshold;
    const isCritical = isInverted ? isOverThreshold : isOverThreshold;

    if (isCritical) return 'border-red-500 bg-red-500/10';
    if (value >= threshold * 0.7) return 'border-yellow-500 bg-yellow-500/10';
    return 'border-green-500 bg-green-500/10';
  };

  const getTextColor = () => {
    const isOverThreshold = value >= threshold;
    const isCritical = isInverted ? isOverThreshold : isOverThreshold;

    if (isCritical) return 'text-red-400';
    if (value >= threshold * 0.7) return 'text-yellow-400';
    return 'text-green-400';
  };

  // Calculate percentage for progress bar
  const percentage = Math.min((value / threshold) * 100, 100);

  return (
    <motion.div
      className={`relative p-6 rounded-lg border-2 transition-all duration-300 ${getStatusColor()}`}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      {/* Icon and Label */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <div className={`${getTextColor()}`}>
            {icon}
          </div>
          <h3 className="text-sm font-medium text-gray-300">{label}</h3>
        </div>
      </div>

      {/* Value Display */}
      <div className="mb-3">
        <motion.div
          className={`text-4xl font-bold ${getTextColor()}`}
          key={value} // Force re-render on value change
          initial={{ scale: 1 }}
          animate={{ scale: [1, 1.1, 1] }}
          transition={{ duration: 0.3 }}
        >
          {value.toFixed(1)}
          <span className="text-xl ml-1">{unit}</span>
        </motion.div>
      </div>

      {/* Progress Bar */}
      <div className="relative h-2 bg-gray-700 rounded-full overflow-hidden">
        <motion.div
          className={`absolute top-0 left-0 h-full transition-colors duration-300 ${
            percentage >= 100
              ? 'bg-red-500'
              : percentage >= 70
              ? 'bg-yellow-500'
              : 'bg-green-500'
          }`}
          initial={{ width: 0 }}
          animate={{ width: `${percentage}%` }}
          transition={{ duration: 0.5, ease: 'easeOut' }}
        />
      </div>

      {/* Threshold Indicator */}
      <div className="mt-2 text-xs text-gray-500">
        Threshold: {threshold}{unit}
      </div>

      {/* Warning Pulse Effect when over threshold */}
      {value >= threshold && (
        <motion.div
          className="absolute inset-0 border-2 border-red-500 rounded-lg pointer-events-none"
          animate={{
            opacity: [0.5, 0, 0.5],
          }}
          transition={{
            duration: 1.5,
            repeat: Infinity,
            ease: 'easeInOut',
          }}
        />
      )}
    </motion.div>
  );
}

