  return PROJECT_CONFIG.forbiddenPatterns.some(pattern => pattern.test(url));
}

export function validateCategory(category: string): category is AllowedCategory {
  return PROJECT_CONFIG.allowedCategories.includes(category as AllowedCategory);
}

// src/context/SystemStatusContext.tsx
'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';

export interface SystemMetrics {
  cpu: number;
  memory: number;
  requestRate: number;
  activeConnections: number;
  errorRate: number;
}

export interface LogEntry {
  id: string;
  timestamp: Date;
  category: 'auth' | 'api' | 'database' | 'security' | 'system';
  message: string;
  severity: 'info' | 'warning' | 'error' | 'critical';
}

export type SystemHealth = 'healthy' | 'degraded' | 'critical';

interface SystemStatusContextType {
  metrics: SystemMetrics;
  systemHealth: SystemHealth;
  logs: LogEntry[];
  addLog: (log: Omit<LogEntry, 'id' | 'timestamp'>) => void;
}

const defaultMetrics: SystemMetrics = {
  cpu: 25,
  memory: 40,
  requestRate: 120,
  activeConnections: 45,
  errorRate: 0.5,
};

const SystemStatusContext = createContext<SystemStatusContextType | undefined>(undefined);

export const useSystemStatus = () => {
  const context = useContext(SystemStatusContext);
  if (!context) {
    throw new Error('useSystemStatus must be used within SystemStatusProvider');
  }
  return context;
};

export const SystemStatusProvider = ({ children }: { children: React.ReactNode }) => {
  const [metrics, setMetrics] = useState<SystemMetrics>(defaultMetrics);
  const [logs, setLogs] = useState<LogEntry[]>([
    {
      id: '1',
      timestamp: new Date(),
      category: 'system',
      message: 'System initialized successfully',
      severity: 'info',
    },
    {
      id: '2',
      timestamp: new Date(Date.now() - 5000),
      category: 'security',
      message: 'Ghost detection active - all clear',
      severity: 'info',
    },
  ]);

  // Calculate system health based on metrics
  const calculateSystemHealth = (m: SystemMetrics): SystemHealth => {
    if (m.cpu >= 90 || m.memory >= 90 || m.errorRate >= 10) return 'critical';
    if (m.cpu >= 70 || m.memory >= 75 || m.errorRate >= 5) return 'degraded';
    return 'healthy';
  };

  const systemHealth = calculateSystemHealth(metrics);

  const addLog = (log: Omit<LogEntry, 'id' | 'timestamp'>) => {
    const newLog: LogEntry = {
      ...log,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
    };
    setLogs((prev) => [newLog, ...prev].slice(0, 50)); // Keep last 50 logs
  };

  // Simulate realtime metrics updates
  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics((prev) => {
        // Simulate natural metric fluctuations
        const cpuChange = (Math.random() - 0.5) * 10;
        const memoryChange = (Math.random() - 0.5) * 5;
        const requestRateChange = (Math.random() - 0.5) * 50;
        const connectionsChange = Math.floor((Math.random() - 0.5) * 10);
        const errorRateChange = (Math.random() - 0.5) * 0.5;

        const newMetrics = {
          cpu: Math.max(5, Math.min(95, prev.cpu + cpuChange)),
          memory: Math.max(20, Math.min(90, prev.memory + memoryChange)),
          requestRate: Math.max(0, Math.min(1000, prev.requestRate + requestRateChange)),
          activeConnections: Math.max(0, Math.min(500, prev.activeConnections + connectionsChange)),
          errorRate: Math.max(0, Math.min(15, prev.errorRate + errorRateChange)),
        };

        // Log significant changes
        if (newMetrics.cpu > 80 && prev.cpu <= 80) {
          addLog({
            category: 'system',
            message: `High CPU usage detected: ${newMetrics.cpu.toFixed(1)}%`,
            severity: 'warning',
          });
        }

        if (newMetrics.errorRate > 5 && prev.errorRate <= 5) {
          addLog({
            category: 'security',
            message: `Elevated error rate: ${newMetrics.errorRate.toFixed(1)}%`,
            severity: 'error',
          });
        }

        return newMetrics;
      });
    }, 3000); // Update every 3 seconds

    // Subscribe to realtime Supabase events (if connected)
    const channel = supabase
      .channel('system_stats_channel')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'system_stats',
        },
        (payload) => {
          addLog({
            category: 'database',
            message: `Database event: ${payload.eventType}`,
            severity: 'info',
          });
        }
      )
      .subscribe();

    return () => {
      clearInterval(interval);
      supabase.removeChannel(channel);
    };
  }, []);

  return (
    <SystemStatusContext.Provider value={{ metrics, systemHealth, logs, addLog }}>
      {children}
    </SystemStatusContext.Provider>
  );
};

// src/hooks/useSafeMode.ts
// 🧊 Adaptive Safe-Mode Hook
// Überwacht System-Metriken und aktiviert automatisch Drosselung bei hoher Last

import { useState, useEffect, useCallback } from 'react';
import { useSystemStatus } from '@/context/SystemStatusContext';

export interface SafeModeConfig {
  criticalThreshold: number;  // CPU-Last ab der Safe-Mode aktiviert wird (%)
  recoveryThreshold: number;  // CPU-Last unter der Safe-Mode deaktiviert wird (%)
  cooldownDuration: number;   // Mindest-Dauer im Safe-Mode (ms)
}

export interface SafeModeState {
  isSafeMode: boolean;
  reason: 'none' | 'cpu' | 'memory' | 'ghost' | 'manual';
  activatedAt: Date | null;
  canRecover: boolean;
}

const DEFAULT_CONFIG: SafeModeConfig = {
  criticalThreshold: 90,
  recoveryThreshold: 60,
  cooldownDuration: 5000, // 5 Sekunden
};

export function useSafeMode(config: Partial<SafeModeConfig> = {}) {
  const { metrics, systemHealth } = useSystemStatus();
  const mergedConfig = { ...DEFAULT_CONFIG, ...config };

  const [state, setState] = useState<SafeModeState>({
    isSafeMode: false,
    reason: 'none',
    activatedAt: null,
    canRecover: false,
  });

  // Safe-Mode aktivieren
  const activateSafeMode = useCallback((reason: SafeModeState['reason']) => {
    console.warn(`⚠️  CRITICAL HEAT DETECTED. ACTIVATING SAFE MODE (Reason: ${reason})`);

    setState({
      isSafeMode: true,
      reason,
      activatedAt: new Date(),
      canRecover: false,
    });

    // Optional: API-Call um Backend über Safe-Mode zu informieren
    // fetch('/api/system/safe-mode', { method: 'POST', body: JSON.stringify({ active: true }) });
  }, []);

  // Safe-Mode deaktivieren
  const deactivateSafeMode = useCallback(() => {
    console.log('✅ SYSTEM RECOVERED. DEACTIVATING SAFE MODE.');

    setState({
      isSafeMode: false,
      reason: 'none',
      activatedAt: null,
      canRecover: false,
    });

    // Optional: API-Call
    // fetch('/api/system/safe-mode', { method: 'POST', body: JSON.stringify({ active: false }) });
  }, []);

  // CPU-Last überwachen
  useEffect(() => {
    // Safe-Mode aktivieren bei kritischer Last
    if (!state.isSafeMode && metrics.cpu > mergedConfig.criticalThreshold) {
      activateSafeMode('cpu');
    }

    // Ghost-Alarm basierend auf systemHealth
    if (!state.isSafeMode && systemHealth === 'critical') {
      activateSafeMode('ghost');
    }

    // Recovery-Check: Nach Cooldown-Periode prüfen, ob Erholung möglich
    if (state.isSafeMode && state.activatedAt) {
      const elapsed = Date.now() - state.activatedAt.getTime();

      if (elapsed > mergedConfig.cooldownDuration) {
        setState(prev => ({ ...prev, canRecover: true }));
      }
    }

    // Automatische Erholung
    if (
      state.isSafeMode &&
      state.canRecover &&
      metrics.cpu < mergedConfig.recoveryThreshold &&
      systemHealth === 'healthy'
    ) {
      deactivateSafeMode();
    }
  }, [
    metrics.cpu,
    systemHealth,
    state.isSafeMode,
    state.activatedAt,
    state.canRecover,
    mergedConfig,
    activateSafeMode,
    deactivateSafeMode,
  ]);

  // Manuelle Steuerung (für Admin-Panel)
  const forceActivate = useCallback(() => {
    activateSafeMode('manual');
  }, [activateSafeMode]);

  const forceDeactivate = useCallback(() => {
    deactivateSafeMode();
  }, [deactivateSafeMode]);

  return {
    ...state,
    config: mergedConfig,
    metrics,
    systemHealth,
    forceActivate,
    forceDeactivate,
  };
}

// UI-Helper: Gibt CSS-Klassen basierend auf Safe-Mode zurück
export function useSafeModeStyles() {
  const { isSafeMode, reason } = useSafeMode();

  const frameClasses = isSafeMode
    ? 'bg-blue-900 shadow-[0_0_50px_rgba(0,100,255,0.5)] transition-all duration-1000'
    : 'bg-[var(--metallic-gradient)] animate-[metallic-pulse_4s_infinite] bg-[length:200%_200%]';

  const textClasses = isSafeMode ? 'blur-sm grayscale' : 'blur-0 grayscale-0';

  const glowClasses = isSafeMode
    ? 'opacity-30 saturate-50'
    : 'opacity-100 saturate-100';

  const pulseSpeed = isSafeMode ? 'animate-pulse-slow' : 'animate-pulse';

  return {
    isSafeMode,
    reason,
    frameClasses,
    textClasses,
    glowClasses,
    pulseSpeed,
  };
}

// src/lib/metrics-collector.ts
// 🚨 System Metrics Collector - Prometheus Bridge
// Collects real system metrics and pushes to Supabase

import axios from 'axios';
import { createClient } from '@supabase/supabase-js';

const PROMETHEUS_URL = process.env.PROMETHEUS_URL || 'http://localhost:9090/api/v1/query';
const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

interface SystemMetrics {
  cpu_load: number;
  db_connections: number;
  memory_usage: number;
  status: 'nominal' | 'busy' | 'stress' | 'ghost_detected';
}

/**
 * Query Prometheus for system metrics
 */
async function queryPrometheus(query: string): Promise<number> {
  try {
    const response = await axios.get(PROMETHEUS_URL, {
      params: { query },
      timeout: 5000
    });

    const result = response.data?.data?.result?.[0];
    if (result && result.value && result.value[1]) {
      return parseFloat(result.value[1]);
    }

    return 0;
  } catch (error) {
    console.error(`Prometheus query failed: ${query}`, error);
    return 0;
  }
}

/**
 * Collect simulated metrics (fallback when Prometheus unavailable)
 */
function getSimulatedMetrics(): SystemMetrics {
  const cpu_load = Math.floor(Math.random() * 60) + 10; // 10-70%
  const db_connections = Math.floor(Math.random() * 10) + 2; // 2-12 connections
  const memory_usage = Math.floor(Math.random() * 50) + 30; // 30-80%

  let status: SystemMetrics['status'] = 'nominal';
  if (cpu_load > 80) status = 'stress';
  else if (cpu_load > 50) status = 'busy';

  return {
    cpu_load,
    db_connections,
    memory_usage,
    status
  };
}

/**
 * Collect real metrics from Prometheus
 */
async function collectRealMetrics(): Promise<SystemMetrics> {
  try {
    // CPU Load (100 - idle percentage)
    const cpuQuery = '100 - (avg by (instance) (irate(node_cpu_seconds_total{mode="idle"}[5m])) * 100)';
    const cpu_load = await queryPrometheus(cpuQuery);

    // Database Connections
    const dbQuery = 'pg_stat_activity_count';
    const db_connections = await queryPrometheus(dbQuery);

    // Memory Usage
    const memQuery = '(1 - (node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)) * 100';
    const memory_usage = await queryPrometheus(memQuery);

    // Determine status
    let status: SystemMetrics['status'] = 'nominal';
    if (cpu_load > 85 || memory_usage > 90) {
      status = 'stress';
    } else if (cpu_load > 60 || memory_usage > 75) {
      status = 'busy';
    }

    return {
      cpu_load: Math.max(0, Math.min(100, cpu_load)),
      db_connections: Math.max(0, db_connections),
      memory_usage: Math.max(0, Math.min(100, memory_usage)),
      status
    };
  } catch (error) {
    console.warn('Failed to collect real metrics, using simulated data');
    return getSimulatedMetrics();
  }
}

/**
 * Push metrics to Supabase
 */
async function pushMetricsToSupabase(metrics: SystemMetrics) {
  try {
    const { error } = await supabase
      .from('system_stats')
      .insert({
        cpu_load: metrics.cpu_load,
        db_connections: metrics.db_connections,
        status: metrics.status,
        created_at: new Date().toISOString()
      });

    if (error) {
      console.error('Failed to push metrics to Supabase:', error.message);
    } else {
      console.log(`📊 Metrics synced: CPU ${metrics.cpu_load.toFixed(1)}% | DB ${metrics.db_connections} | Status: ${metrics.status}`);
    }
  } catch (error) {
    console.error('Supabase push error:', error);
  }
}

/**
 * Main metrics collection loop
 */
export async function syncSystemMetrics() {
  console.log('🚀 Metrics Collector started');

  // Collect and push metrics every 10 seconds
  const interval = setInterval(async () => {
    try {
      const metrics = await collectRealMetrics();
      await pushMetricsToSupabase(metrics);
    } catch (error) {
      console.error('Metrics collection cycle failed:', error);
    }
  }, 10000); // 10 seconds

  // Cleanup on process termination
  process.on('SIGTERM', () => {
    console.log('🛑 Metrics Collector shutting down...');
    clearInterval(interval);
    process.exit(0);
  });

  process.on('SIGINT', () => {
    console.log('🛑 Metrics Collector interrupted');
    clearInterval(interval);
    process.exit(0);
  });
}

// Run if executed directly
if (require.main === module) {
  syncSystemMetrics();
}

