async function run() {
  const res = await fetch('https://raw.githubusercontent.com/leakyMirror/map-of-europe/master/TopoJSON/europe.topojson');
  const topoData = await res.json() as any;

  // Convert TopoJSON to GeoJSON FeatureCollection
  const geojson = topojson.feature(topoData, topoData.objects.europe) as any;

  // Setup D3 projection for Europe
  // Width 960, Height 680
  const width = 960;
  const height = 680;

  // Conic Conformal or Mercator projection centered around central Europe (approx 11°E, 54°N)
  const projection = d3.geoConicConformal()
    .center([13, 53])
    .parallels([35, 65])
    .rotate([-10, 0])
    .scale(1020)
    .translate([width / 2, height / 2 + 30]);

  const pathGenerator = d3.geoPath().projection(projection);

  const countryPaths: any[] = [];

  for (const feature of geojson.features) {
    const id = feature.id as string;
    const name = feature.properties.NAME as string;
    const path = pathGenerator(feature);

    // Calculate centroid
    let centroid = pathGenerator.centroid(feature);
    if (!centroid || isNaN(centroid[0]) || isNaN(centroid[1])) {
      centroid = [0, 0];
    }

    // Round path numbers to 1 decimal place to optimize size
    const cleanPath = path ? path.replace(/([0-9]+\.[0-9]{2,})/g, (match) => parseFloat(match).toFixed(1)) : '';

    const mapping = COUNTRY_MAPPING[id];

    countryPaths.push({
      id,
      name,
      germanName: mapping ? mapping.germanName : name,
      region: mapping ? mapping.region : 'Europa',
      path: cleanPath,
      center: [Math.round(centroid[0]), Math.round(centroid[1])]
    });
  }

  // Filter out countries far outside Europe like Israel/Azerbaijan/Armenia/Georgia if desired, or keep relevant
  const filtered = countryPaths.filter(c => c.path && !['IL', 'AZ', 'AM', 'GE', 'CY', 'TR'].includes(c.id));

  console.log(`Generated ${filtered.length} country paths.`);
  console.log('Sample center:', filtered.find(c => c.id === 'DE'));

  const fileContent = `// Pre-projected SVG paths for Europe vector map
// Coordinate space: 960 x 680 (D3 geoConicConformal)

export interface EuropeCountryPath {
  id: string;
  name: string;
  germanName: string;
  region: string;
  path: string;
  center: [number, number];
}

export const EUROPE_MAP_DIMENSIONS = {
  width: 960,
  height: 680,
  viewBox: "0 0 960 680"
};

export const EUROPE_COUNTRY_PATHS: EuropeCountryPath[] = ${JSON.stringify(filtered, null, 2)};
`;

  fs.writeFileSync('src/data/europe-map-paths.ts', fileContent, 'utf-8');
  console.log('Successfully written to src/data/europe-map-paths.ts');
}

run().catch(console.error);

/**
 * Verification script for URLs in the European Noble Houses directory.
 * Can be run with: npx tsx scripts/verify-urls.ts
 */

import { allHouses } from '../src/data';

interface UrlCheckResult {
  houseId: string;
  houseName: string;
  urlType: string;
  url: string;
  status: number | string;
  ok: boolean;
}

export async function verifyUrls(sampleSize?: number): Promise<void> {
  const housesToCheck = sampleSize ? allHouses.slice(0, sampleSize) : allHouses;
  console.log(`Starting URL verification for ${housesToCheck.length} houses...`);

  const results: UrlCheckResult[] = [];
  let totalUrls = 0;

  for (const house of housesToCheck) {
    const urlsToCheck: Array<{ type: string; url?: string }> = [
      { type: 'official', url: house.urls.official },
      { type: 'archive', url: house.urls.archive },
      { type: 'museum', url: house.urls.museum },
      { type: 'foundation', url: house.urls.foundation },
      { type: 'encyclopedia', url: house.urls.encyclopedia }
    ];

    for (const { type, url } of urlsToCheck) {
      if (!url) continue;
      totalUrls++;

      try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 5000);

        const response = await fetch(url, {
          method: 'HEAD',
          signal: controller.signal,
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Corpus-Nobilium-Verifier/1.0'
          }
        });
        clearTimeout(timeout);

        results.push({
          houseId: house.id,
          houseName: house.name,
          urlType: type,
          url,
          status: response.status,
          ok: response.status >= 200 && response.status < 400
        });
      } catch (err: any) {
        results.push({
          houseId: house.id,
          houseName: house.name,
          urlType: type,
          url,
          status: err?.name === 'AbortError' ? 'TIMEOUT' : 'NETWORK_ERROR',
          ok: false
        });
      }
    }
  }

  const successful = results.filter((r) => r.ok).length;
  console.log(`\nVerification Summary:`);
  console.log(`Total URLs checked: ${totalUrls}`);
  console.log(`Successful (Status 200/300): ${successful}`);
  console.log(`Errors/Timeouts: ${totalUrls - successful}`);
}

// If invoked directly via CLI
if (process.argv[1]?.endsWith('verify-urls.ts')) {
  verifyUrls(10).then(() => {
    console.log('Sample verification completed.');
  });
}

