interface CrestInteractionOverlayProps {
  house: House;
  position: { x: number; y: number };
  containerRect?: DOMRect | null;
  onSelectHouse: (house: House) => void;
}

export const CrestInteractionOverlay: React.FC<CrestInteractionOverlayProps> = ({
  house,
  position,
  containerRect,
  onSelectHouse
}) => {
  const motto = getHouseMotto(house);

  const diplomaticStatus: DiplomaticStatus = 
    house.DiplomaticStatus || house.diplomaticStatus || 'Consulting';
  const statusConfig = DIPLOMATIC_STATUS_MAP[diplomaticStatus] || DIPLOMATIC_STATUS_MAP.Consulting;
  const flag = COUNTRY_FLAGS[house.country] || '🏰';

  // Calculate smart tooltip coordinates so it stays well within viewport limits
  const tooltipWidth = 350;
  const tooltipHeight = 310;

  const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1200;
  const viewportHeight = typeof window !== 'undefined' ? window.innerHeight : 800;

  const containerLeft = containerRect?.left || 0;
  const containerTop = containerRect?.top || 0;

  let computedLeft = position.x + containerLeft + 16;
  let computedTop = position.y + containerTop - 10;

  // Flip horizontally if near right edge
  if (computedLeft + tooltipWidth > viewportWidth - 20) {
    computedLeft = position.x + containerLeft - tooltipWidth - 16;
  }

  // Ensure left is not offscreen
  if (computedLeft < 16) {
    computedLeft = 16;
  }

  // Flip vertically if near bottom edge
  if (computedTop + tooltipHeight > viewportHeight - 20) {
    computedTop = position.y + containerTop - tooltipHeight - 10;
  }

  // Ensure top is not offscreen
  if (computedTop < 16) {
    computedTop = 16;
  }

  return (
    <div
      id={`wappen-interaktions-overlay-${house.id}`}
      className="pointer-events-none fixed z-50 bg-[#170E12]/98 text-[#FAF6EE] backdrop-blur-md p-4 sm:p-5 rounded-2xl border-2 border-[#C5A059] shadow-[0_20px_50px_rgba(0,0,0,0.8)] w-[350px] max-w-[92vw] transition-all duration-100 ease-out space-y-3 animate-in fade-in zoom-in-95"
      style={{
        left: `${computedLeft}px`,
        top: `${computedTop}px`
      }}
    >
      {/* Top Gold Hairline & Decorative Glow */}
      <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#8B1E2F] via-[#E5C170] to-[#10B981] rounded-t-2xl shadow-[0_0_12px_#E5C170]" />

      {/* Header: House Type, Flag, Country, Seat */}
      <div className="flex items-start justify-between gap-2 border-b border-[#3D252C] pb-2.5">
        <div className="flex items-center gap-2.5 min-w-0">
          <div className="shrink-0 p-1 bg-[#28151D] rounded-lg border border-[#482833]">
            <HeraldicShield
              motif={house.crestMotif}
              houseName={house.name}
              diplomaticStatus={diplomaticStatus}
              size="sm"
            />
          </div>
          <div className="min-w-0">
            <span className="inline-block px-2 py-0.5 rounded text-[10px] font-bold tracking-wider uppercase bg-[#2E181F] text-[#E5C170] border border-[#C5A059]/40 mb-0.5">
              {house.type}
            </span>
            <div className="text-xs text-[#D1C2B0] font-medium flex items-center gap-1 truncate">
              <span>{flag}</span>
              <span className="truncate">{house.country}</span>
              <span>•</span>
              <span className="truncate text-[#A89887]">{house.seat}</span>
            </div>
          </div>
        </div>

        <BesaEidBadge
          house={house}
          size="sm"
          variant="card-stamp"
        />
      </div>

      {/* House Name & Historical Period */}
      <div>
        <h3 className="font-serif font-bold text-base text-[#FAF6EE] leading-snug tracking-tight">
          {house.name}
        </h3>
        {house.altNames && house.altNames.length > 0 && (
          <p className="text-[11px] text-[#A89887] italic font-serif">
            ehem. {house.altNames.join(', ')}
          </p>
        )}
      </div>

      {/* SECTION 1: Familienmotto (Family Motto) - KEY REQUIREMENT */}
      <div 
        id={`overlay-motto-section-${house.id}`}
        className="bg-[#24131A] p-3 rounded-xl border border-[#4A2A35] relative overflow-hidden space-y-1 shadow-inner"
      >
        <div className="flex items-center justify-between text-[10px] uppercase tracking-wider font-bold text-[#E5C170]">
          <span className="flex items-center gap-1.5">
            <Crown className="w-3.5 h-3.5 text-[#E5C170]" />
            <span>Familienmotto & Wahlspruch</span>
          </span>
          <span className="text-[9px] text-[#A89887] font-mono">
            {motto.sourceType === 'historical' ? 'Historisch' : 'Dynastisch'}
          </span>
        </div>

        <div className="pt-0.5">
          <div className="text-xs font-serif font-bold text-[#FAF6EE] italic flex items-start gap-1">
            <Quote className="w-3 h-3 text-[#C5A059] shrink-0 mt-0.5 rotate-180" />
            <span className="leading-snug text-[#F5E6D3]">"{motto.latinOrNative}"</span>
          </div>
          <div className="text-[11px] text-[#D1C2B0] pl-4 pt-0.5 leading-snug">
            {motto.translationDe}
          </div>
        </div>
      </div>

      {/* SECTION 2: Exakter diplomatischer Status - KEY REQUIREMENT */}
      <div 
        id={`overlay-diplomatic-status-section-${house.id}`}
        className="bg-[#1C1014] p-3 rounded-xl border border-[#3D222B] space-y-2"
      >
        <div className="flex items-center justify-between">
          <span className="text-[10px] uppercase font-bold tracking-wider text-[#A89887] flex items-center gap-1">
            <Award className="w-3.5 h-3.5 text-[#10B981]" />
            <span>Exakter diplomatischer Status:</span>
          </span>

          {/* Exact Diplomatic Status Pill */}
          <span 
            className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-extrabold border ${
              diplomaticStatus === 'Active'
                ? 'bg-emerald-950/90 text-emerald-300 border-emerald-400 ring-1 ring-emerald-500/40'
                : diplomaticStatus === 'Consulting'
                ? 'bg-amber-950/90 text-amber-300 border-amber-400 ring-1 ring-amber-500/40'
                : 'bg-stone-900 text-stone-300 border-stone-500 ring-1 ring-stone-500/40'
            }`}
          >
            <span className={`w-2 h-2 rounded-full ${statusConfig.dotClass} animate-pulse`} />
            <span>{statusConfig.labelEn} ({statusConfig.labelDe})</span>
          </span>
        </div>

        {/* Detailed Role Breakdown */}
        <div className="text-[11px] text-[#D8C7B5] leading-relaxed space-y-1">
          <div className="flex items-center gap-1.5 font-medium text-[#FAF6EE]">
            <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
            <span>{statusConfig.shortDesc}</span>
          </div>
          <div className="text-[10px] text-[#A89887] pl-5 leading-tight">
            {statusConfig.roleDescription}
          </div>
        </div>

        {/* Exact eID Accreditation Details */}
        <div className="pt-1.5 border-t border-[#311C23] flex items-center justify-between text-[10px] font-mono text-[#9E8E7E]">
          <span className="flex items-center gap-1">
            <BookmarkCheck className="w-3 h-3 text-[#10B981]" />
            <span>BESA eID #AC-2026-{house.id.replace(/[^a-zA-Z0-9]/g, '').slice(0, 6).toUpperCase()}</span>
          </span>
          <span className="text-emerald-400 font-bold">Ratifiziert</span>
        </div>
      </div>

      {/* Footer hint */}
      <div className="flex items-center justify-between pt-1 border-t border-[#3D252C] text-[10px] text-[#A89887]">
        <span className="italic">Gleitendes Overlay • Klicken zum Öffnen</span>
        <span className="text-[#E5C170] font-bold flex items-center gap-0.5">
          <span>Archivblatt</span>
          <ChevronRight className="w-3 h-3" />
        </span>
