                  floodOpacity={glowOpacity * 1.1} 
                />
              </filter>
              {/* Dynamic Linear Gradients for Arcs */}
              <linearGradient id="goldArc" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#8B1E2F" />
