                >
                  <span>Häuser in {activeData.country} im Archiv einsehen</span>
                  <ArrowRight className="w-4 h-4 text-[#8B1E2F]" />
                </button>
              )}
            </div>
          ) : (
            <div className="bg-white p-8 rounded-2xl border border-[#E3D9C9] text-center text-xs text-[#6C5D50]">
