            <span>Aktiver eID-Pakt: 10 globale & europäische Friedenssitze harmonisiert</span>
          </div>
          <span>BESA eID • Schweizerische Eidgenossenschaft • eIDAS DEU-TR03110</span>
        </div>

      </div>
    </div>
  );
};

import React from 'react';
