export function getHouseMotto(house: House): HouseMotto {
  // 1. Check if crestMotif explicitly contains a motto
  if (house.crestMotif) {
    const motif = house.crestMotif;
    const mottoMatch = motif.match(/(?:Motto|Familienmotto)[:\s]+['"]?([^'".;]+)['"]?/i);
    if (mottoMatch && mottoMatch[1]) {
      const extracted = mottoMatch[1].trim();
      return {
        latinOrNative: extracted,
        translationDe: `Gegenstand der Blasonierung von ${house.name}`,
        sourceType: 'extracted'
      };
    }
  }

  // 2. Check historical lookup by house name key
  const nameLower = house.name.toLowerCase();
  for (const [key, motto] of Object.entries(HISTORICAL_MOTTOS)) {
    if (nameLower.includes(key)) {
      return motto;
    }
  }

  // 3. Fallback: Deterministic selection from traditional heraldic mottos based on house ID string hash
  let hash = 0;
  for (let i = 0; i < house.id.length; i++) {
    hash = (hash << 5) - hash + house.id.charCodeAt(i);
    hash |= 0;
  }
  const index = Math.abs(hash) % TRADITIONAL_MOTTOS.length;
  return TRADITIONAL_MOTTOS[index];
}

import { House, HistoricalEpochKey, HistoricalEpoch, CenturyStat, DiplomaticStatus } from '../types';

/**
 * Extracts the earliest historical year mentioned in a house's period string.
 * Handles formats like:
 * - "1061–heute (Könige von Preußen...)" -> 1061
 * - "750/1070–heute..." -> 750
 * - "1238/1687–heute..." -> 1238
 * - "14. Jh.–heute..." -> 1300
 */
export function extractHouseStartYear(period: string): number {
  if (!period) return 1200;

  // Check for century notation like "11. Jh." or "12. Jahrhundert"
  const centuryMatch = period.match(/(\d{1,2})\.\s*(?:Jh\.|Jahrhundert)/i);
  if (centuryMatch) {
    const c = parseInt(centuryMatch[1], 10);
    return (c - 1) * 100;
  }

  // Find all 3 or 4 digit years
  const matches = period.match(/\b(\d{3,4})\b/g);
  if (matches && matches.length > 0) {
    const years = matches
      .map((m) => parseInt(m, 10))
      .filter((y) => y >= 600 && y <= 2026);
    if (years.length > 0) {
      return Math.min(...years);
    }
  }

  return 1200;
}

